// 上层统一复核原权源及真实提交史，低层writer仍各自只写唯一拥有的业务记录。
#include "political_successor_round_business.hpp"
namespace hanmo::resident {
Status validate_political_successor_round_sources(const PoliticalSuccessorRoundBusinessContext& x){const auto& n=x.sources.nominations;if(x.state.version!=1||&n.state!=&x.state)return common_failure("PoliticalSuccessorRoundCandidateMismatch");return validate_political_successor_round_accessions({x.sources,x.state});}
Status validate_political_successor_rounds(const PoliticalSuccessorRoundBusinessContext& x){if(!x.result_match)return common_failure("PoliticalSuccessorRoundResultReadRequired");auto valid=validate_political_successor_round_sources(x);return valid.ok?validate_political_successor_round_player_results(x.sources.nominations.common,x.state,x.result_match):valid;}
Outcome<PoliticalSuccessorRoundQuote> preview_political_successor_round(const PoliticalSuccessorRoundBusinessContext& x,const StableId& actor,const PoliticalSuccessorRoundCommand& command){auto valid=validate_political_successor_rounds(x);if(!valid.ok)return {false,{},valid.error};return std::visit([&](const auto& c)->Outcome<PoliticalSuccessorRoundQuote>{using T=std::decay_t<decltype(c)>;if constexpr(std::is_same_v<T,PoliticalAccedeNextSuccession>){auto q=preview_political_successor_round_accession({x.sources,x.state},actor,c);if(!q.ok)return {false,{},q.error};return {true,{q.value.identity,actor,command,std::move(q.value)},{}};}else{auto q=preview_political_successor_round_nomination(x.sources.nominations,actor,PoliticalSuccessorRoundNominationCommand{c});if(!q.ok)return {false,{},q.error};return {true,{q.value.identity,actor,command,std::move(q.value)},{}};}},command);}
// 正式写入前沿相同候选重新预览；外部quote不能替换原authority、原接受或本次文书。
Outcome<PoliticalSuccessorRoundEffects> apply_political_successor_round_in_candidate(CommonStore& common,OrganizationState& organizations,PoliticalSuccessorRoundState& state,const PoliticalSuccessorRoundBusinessContext& x,const StableId& actor,const PoliticalSuccessorRoundCommand& command,const PoliticalSuccessorRoundQuote& quote){const auto& a=common.state().identity;const auto& b=quote.identity;if(&common!=&x.sources.nominations.common||&organizations!=&x.sources.nominations.organizations||&state!=&x.state||actor!=quote.actor_id||std::tie(a.world_id,a.execution_epoch,a.revision,a.tick)!=std::tie(b.world_id,b.execution_epoch,b.revision,b.tick)||!compare_boundary(encode_political_successor_round_command(command),encode_political_successor_round_command(quote.command)).exact()||command.index()!=quote.command.index())return {false,{},common_failure("StalePoliticalSuccessorRoundQuote").error};auto fresh=preview_political_successor_round(x,actor,command);if(!fresh.ok)return {false,{},fresh.error};return std::visit([&](const auto& c)->Outcome<PoliticalSuccessorRoundEffects>{using T=std::decay_t<decltype(c)>;if constexpr(std::is_same_v<T,PoliticalAccedeNextSuccession>){auto id=apply_political_successor_round_accession_in_candidate(common,organizations,state,{x.sources,state},actor,c,std::get<PoliticalSuccessorRoundAccessionQuote>(fresh.value.details));if(!id.ok)return {false,{},id.error};const auto* record=state.accessions.find(id.value);if(!record)return {false,{},common_failure("PoliticalSuccessorRoundAccessionSourceRequired",id.value).error};return {true,{id.value,record->office_change_fact_id},{}};}else{auto id=apply_political_successor_round_nomination_in_candidate(common,state,x.sources.nominations,actor,PoliticalSuccessorRoundNominationCommand{c},std::get<PoliticalSuccessorRoundNominationQuote>(fresh.value.details));return id.ok?Outcome<PoliticalSuccessorRoundEffects>{true,{id.value,{}},{}}:Outcome<PoliticalSuccessorRoundEffects>{false,{},id.error};}},command);}
}
